package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.controller.content.ContentDtos;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.content.*;
import com.lianxibu.site.service.identity.IdentityService;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;

/** Actual initial owner command. Only fictional scopes, native intent/receipt, no newly sent model request. */
class OwnerReportInitialTest {
 boolean mysql(){return false;}InitialReportIntentTest h;OwnerReportInitialService service;Clock clock;boolean allowed=true;
 IdentityService.Actor owner=new IdentityService.Actor("fictional-owner","owner");
 @BeforeEach void setup(){h=new InitialReportIntentTest(){@Override GenerationJdbcStoreTest fixture(){return OwnerReportInitialTest.this.mysql()?new GenerationJdbcStoreMySqlTest():new GenerationJdbcStoreTest();}};h.setup();clock=Clock.fixed(Instant.parse("2026-01-02T01:00:00.123456Z"),ZoneOffset.UTC);allowed=true;
  for(String column:List.of("slot_state VARCHAR(16) DEFAULT 'free' NOT NULL","slot_revision BIGINT DEFAULT 0 NOT NULL","fencing_token BIGINT DEFAULT 0 NOT NULL","job_id VARCHAR(64)","holder VARCHAR(64)","lease_until TIMESTAMP","occupied_since TIMESTAMP"))h.f.jdbc.execute("ALTER TABLE worker_lock ADD COLUMN "+column);compose();}
 void compose(){service=new OwnerReportInitialService(h.f.source,h.store,new JdbcReportInitialActions(h.f.source),new ReportPreparedInputService(h.f.source,new DataSourceTransactionManager(h.f.source)),h.f.writes,clock,()->allowed);}
 ContentService.GenerationIntentWrite request(){var day=h.day;var zone=ZoneId.of("Asia/Shanghai");return new ContentService.GenerationIntentWrite("daily",day.atStartOfDay(zone).toInstant(),day.plusDays(1).atStartOfDay(zone).toInstant(),"Asia/Shanghai","initial",null,"Fictional first natural report");}
 ContentService.Job act(String key){return ReportOriginalCompletionTest.utc(()->service.generationIntent(owner,request(),key,"fictional-csrf","https://fictional.invalid"));}
 @Test void FirstOwnerRequestCreatesOnlyStableIntentAndPermanentOriginalReceipt(){var first=act("fictional-initial-create");assertEquals("generation_intent",first.recordKind());assertEquals("waiting_input",first.state());assertEquals(0,first.intentRevision());assertNull(first.inputCutoffAt());assertEquals("partial",first.coverage().state());assertEquals("not_frozen",first.coverage().missingInputs().getFirst().reason());assertEquals(List.of("waiting_input"),first.waitingReasons());assertEquals(first,act("fictional-initial-create"));assertEquals(2L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));assertEquals(0L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind IN ('logical_task','ai_attempt','snapshot_part')",Long.class));assertEquals("waiting_input",ContentDtos.job(first).get("state"));}
 @Test void OriginalResponseReplaysBeforePauseClockOrLaterIntentSlotChanges(){var first=act("fictional-initial-replay");allowed=false;clock=mock(Clock.class);h.f.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",first.id());h.f.jdbc.update("UPDATE worker_lock SET slot_revision=slot_revision+1");compose();assertEquals(first,act("fictional-initial-replay"));verifyNoInteractions(clock);var failure=assertThrows(IdentityService.Rejected.class,()->service.generationIntent(new IdentityService.Actor("fictional-other","owner"),request(),"fictional-initial-replay","fictional-csrf","https://fictional.invalid"));assertEquals(IdentityService.Refusal.IDENTITY_CONFLICT,failure.refusal());}
 @Test void AnotherKeyGetsSameFirstResourceAndNaturalWeeklyMonthlyNeverCreatesBudget(){var first=act("fictional-initial-a");assertEquals(first,act("fictional-initial-b"));var zone=ZoneId.of("Asia/Shanghai");for(var kind:List.of("weekly","monthly")){LocalDate day=kind.equals("weekly")?LocalDate.parse("2026-01-04"):LocalDate.parse("2026-01-31");LocalDate start=kind.equals("weekly")?day.minusDays(6):day.withDayOfMonth(1);var req=new ContentService.GenerationIntentWrite(kind,start.atStartOfDay(zone).toInstant(),day.plusDays(1).atStartOfDay(zone).toInstant(),"Asia/Shanghai","initial",null,"Fictional natural period");assertEquals(kind+"_report",ReportOriginalCompletionTest.utc(()->service.generationIntent(owner,req,"fictional-initial-"+kind,"fictional-csrf","https://fictional.invalid")).taskType());}assertEquals(3L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='generation_intent'",Long.class));assertEquals(0L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='logical_task'",Long.class));}
 @Test void PauseAndReceiptFailureCannotLeaveAnOrphanIntent(){allowed=false;var error=assertThrows(IdentityService.Rejected.class,()->act("fictional-initial-paused"));assertEquals(IdentityService.Refusal.TEMPORARILY_UNAVAILABLE,error.refusal());assertEquals(0L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));allowed=true;h.f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_initial_command_failure CHECK(target_type IS NULL OR target_type<>'report_initial_request')");assertThrows(IdentityService.Rejected.class,()->act("fictional-initial-rollback"));assertEquals(0L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));}
 @Test void InvalidNaturalPeriodModeRevisionOrHeadersAreRejectedBeforeNativeWrite(){var r=request();var badPeriod=new ContentService.GenerationIntentWrite(r.kind(),r.periodStart().plusSeconds(1),r.periodEnd(),r.timezone(),r.mode(),null,r.reason());assertThrows(IllegalArgumentException.class,()->service.generationIntent(owner,badPeriod,"fictional-initial-period","fictional-csrf","https://fictional.invalid"));var bad=new ContentService.GenerationIntentWrite(r.kind(),r.periodStart(),r.periodEnd(),r.timezone(),r.mode(),0L,r.reason());var finalBad=bad;assertThrows(IllegalArgumentException.class,()->service.generationIntent(owner,finalBad,"fictional-initial-revision","fictional-csrf","https://fictional.invalid"));assertThrows(IllegalArgumentException.class,()->service.generationIntent(owner,r,"fictional-initial-header","","https://fictional.invalid"));assertEquals(0L,h.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Long.class));}
 @Test void AlreadyPreparedInitialUsesActualWholeOriginalInputRatherThanCurrentBody()throws Exception{var nativeReport=new ReportNativeGenerationIntegrationTest(){@Override boolean mysql(){return OwnerReportInitialTest.this.mysql();}};nativeReport.setup();var base=nativeReport.h.h.h.f.data.nativeData().fixture().f();var original=nativeReport.h.h.original;clock=Clock.fixed(nativeReport.clock.instant().plusSeconds(1),ZoneOffset.UTC);service=new OwnerReportInitialService(base.source,new JdbcInitialReportIntent(base.source),new JdbcReportInitialActions(base.source),new ReportPreparedInputService(base.source,base.tx),base.writes,clock,()->true);
  var day=original.scope().day();var zone=ZoneId.of("Asia/Shanghai");var req=new ContentService.GenerationIntentWrite("daily",day.atStartOfDay(zone).toInstant(),day.plusDays(1).atStartOfDay(zone).toInstant(),"Asia/Shanghai","initial",null,"Fictional existing prepared report");var first=ReportOriginalCompletionTest.utc(()->service.generationIntent(owner,req,"fictional-initial-prepared","fictional-csrf","https://fictional.invalid"));assertEquals("queued",first.state());assertEquals(original.input().cutoff(),first.inputCutoffAt());assertEquals(original.input().coverageState(),first.coverage().state());assertEquals(1,nativeReport.reportSends);assertNotNull(ContentDtos.job(first));base.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='generation_prepare' AND operator_id=?",new byte[32],JdbcReportPreparedInputs.ACTOR);assertEquals(first,ReportOriginalCompletionTest.utc(()->service.generationIntent(owner,req,"fictional-initial-prepared","fictional-csrf","https://fictional.invalid")));assertThrows(IdentityService.Rejected.class,()->ReportOriginalCompletionTest.utc(()->service.generationIntent(owner,req,"fictional-initial-corrupt-whole","fictional-csrf","https://fictional.invalid")));assertEquals(1,nativeReport.reportSends);}
 @Test void ConstructorIsColdAndNonOwnerRefusesBeforeEveryDependency(){var source=mock(javax.sql.DataSource.class);var intents=mock(JdbcInitialReportIntent.class);var actions=mock(JdbcReportInitialActions.class);var originals=mock(ReportPreparedInputService.class);var writes=mock(SharedWriteExecutor.class);var clock=mock(Clock.class);var cold=new OwnerReportInitialService(source,intents,actions,originals,writes,clock,()->{throw new AssertionError();});assertEquals(IdentityService.Refusal.UNAUTHENTICATED,assertThrows(IdentityService.Rejected.class,()->cold.generationIntent(null,null,null,null,null)).refusal());assertEquals(IdentityService.Refusal.FORBIDDEN,assertThrows(IdentityService.Rejected.class,()->cold.generationIntent(new IdentityService.Actor("fictional-reader","reader"),null,null,null,null)).refusal());verifyNoInteractions(source,intents,actions,originals,writes,clock);}
}
